E=W['model.embed_tokens.weight'].float(); nw=W['model.norm.weight'].float()
def dec(ids): return [tok.decode([i]) for i in ids]
def topdirs(name,k=2,n=12):
    A,B=diff[name]; A=A.float(); B=B.float()
    # delta = B@A (in,out); svd
    U,S,Vh=torch.linalg.svd(B@A/8, full_matrices=False)
    out=[]
    for i in range(k):
        v=Vh[i]*nw
        s=E@v
        out.append((S[i].item(),dec(s.topk(n).indices.tolist()),dec((-s).topk(n).indices.tolist())))
    return out
