def inproj(L,t,n=15,k=3):
    A,B=diff[f'model.layers.{L}.{t}']; B=B.float()
    ln = W[f'model.layers.{L}.input_layernorm.weight' if 'self_attn' in t else f'model.layers.{L}.post_attention_layernorm.weight'].float()
    U,S,Vh=torch.linalg.svd(B@A.float()/8, full_matrices=False)
    for i in range(k):
        s=E@(U[:,i]*ln)
        print(L,t,i,round(S[i].item(),3),dec(s.topk(n).indices.tolist()),dec((-s).topk(n).indices.tolist()))
